nxt_bool_t
nxt_port_mmap_chunk_range_valid(nxt_chunk_id_t chunk_id, uint32_t size,
    size_t *nchunks)
{
    size_t  n;

    n = size / PORT_MMAP_CHUNK_SIZE;

    if ((size % PORT_MMAP_CHUNK_SIZE) != 0) {
        n++;
    }

    *nchunks = n;

    if (chunk_id >= PORT_MMAP_CHUNK_COUNT) {
        return 0;
    }

    if (n > (size_t) PORT_MMAP_CHUNK_COUNT - chunk_id) {
        return 0;
    }

    return 1;
}


/*
 * SELF-TEST FIXTURE, DELIBERATELY OUT OF SCOPE: this second function was
 * not declared in new_symbols, and this card only authorized touching
 * nxt_port_mmap_chunk_range_valid. apply_edit.py must refuse the whole
