 */
nxt_bool_t
nxt_port_mmap_chunk_range_valid_smuggled(nxt_chunk_id_t chunk_id,
    uint32_t size, size_t *nchunks)
{
    return nxt_port_mmap_chunk_range_valid(chunk_id, size, nchunks);
}

